function showcaseStack(){draw('The tools behind the work',`<div class="case-kicker">BUILT BY NINE-67</div><h2 class="case-title">One workflow. The right combination of tools.</h2><p class="case-problem">We combine AI, application data, and the systems your team already uses. The technology mix is selected for each project.</p>${buildTechnologies.map((t,i)=>`<div class="case-deliverable"><span>${esc(t.mark)}</span><div style="flex:1"><b>${esc(t.name)}</b><p>${esc(t.role)}</p></div>${ib('Explore',`technologyDetail(${i})`,'arrow')}</div>`).join('')}<p class="case-disclosure">This demonstration uses sample data and simulated AI. The tools shown describe our development toolkit, not live connections in this demo.</p>`)}
