function sidebarIcon(i){const colors=['#286595','#157b75','#a15d2e','#377550','#7a6a26','#3268a7','#227889','#4e6f86','#a35d40','#207d94','#9a7027','#506a7b','#354c80','#27815b','#315e91','#896342','#2d7864','#38718c','#267e91','#6b7c3c','#9a613d','#286c91','#23786d','#a4682e','#3f6589'];const refined={2:'<path d="M3 4h18l-7 8v7l-4 2v-9z"/>',4:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1"/>',6:'<circle cx="8" cy="6" r="3"/><path d="M2 18v-3a6 6 0 0 1 12 0v3M17 4h5m-5 5h3m-3 5h5m-5 5h3"/>',8:'<path d="M3 3v17h17M7 14l4-5 4 2 5-7"/><circle cx="11" cy="9" r="1"/>',10:'<path d="M3 19v-7a9 9 0 0 1 18 0v7M3 19h18M12 7v2M6 10l1 1m11-1-1 1M12 16l4-4"/><circle cx="12" cy="16" r="1"/>',14:'<path d="M3 21h18M5 17V9m7 8V3m7 14v-5M3 6l5-3"/>',15:'<path d="M3 7h18v13H3zM8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',16:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><path d="m10 14 4-4m-1 0h1v1"/>'};return `<span class="sidebar-symbol" style="--nav-icon:${colors[i]||'#526d7d'}"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">${refined[i]||sidebarSymbols[i]}</svg></span>`}
function showcaseSidebar(){const groups=[['Growth',[0,1,2,12]],['Delivery',toolsList.length>17?[6,7,11,13,17]:toolsList.length>13?[6,7,11,13]:[6,7,11]],['Decisions & planning',toolsList.length>16?[3,4,5,8,9,10,14,15,16]:[3,4,5,8,9,10]]];if(toolsList.length>18)groups.push(['Agents',[18,19,20]]);$('#sidebar').innerHTML=`<a class="showcase-brand" href="https://nine-67.com/" aria-label="Visit Nine-67" style="text-decoration:none;color:inherit"><img class="nine67-logo" src="nine67-logo.png" alt="Nine-67"><span class="sidebar-brand-copy"><b>AI Applications</b><span>by Nine-67</span></span></a><button class="showcase-home ${current<0?'selected':''}" onclick="nav(-1)">${icon('grid')}<span>Our process & technology</span></button><nav class="showcase-navscroll" aria-label="Applications">${groups.map(([name,ids])=>`<section class="sidebar-group"><h2 class="showcase-navlabel">${name}</h2>${ids.map(i=>`<button title="${esc(toolsList[i][0])}" ${current===i?'aria-current="page"':''} class="showcase-navitem ${current===i?'selected':''}" onclick="nav(${i})">${sidebarIcon(i)}<span>${esc(toolsList[i][0])}</span></button>`).join('')}</section>`).join('')}</nav><div class="showcase-sidebottom"><button onclick="showcaseStack()">${icon('link')}<span>Technology & integrations</span>${icon('arrow')}</button><div><span class="showcase-status"></span> Interactive client showcase</div></div>`}
function showcaseHeader(){const p=productStories[current],m=showcaseMeta[current];return `<section class="showcase-brief"><div class="showcase-copy"><div class="showcase-eyebrow"><span>${icon(productIcons[current])}${esc(toolsList[current][0])}</span><b>BUILT BY NINE-67</b></div><h1>${esc(p.title)}</h1><p>${esc(p.desc)}</p><div class="showcase-actions"><button class="showcase-primary" onclick="exploreHeaderStep(${m[5]})">${esc(m[0])} ${icon('arrow')}</button><button class="showcase-secondary" onclick="showProspectExample()">See the use case</button><span>${esc(p.audience)}</span></div></div><button class="showcase-artifact" onclick="exploreHeaderStep(${m[5]})"><div class="artifact-top"><span>${icon(productIcons[current])} SAMPLE OUTPUT</span><span>↗</span></div><h2>${esc(m[1])}</h2><div class="artifact-items">${m.slice(2,5).map((x,i)=>`<div><span>${i===2?icon('check'):'0'+(i+1)}</span>${esc(x)}</div>`).join('')}</div><div class="artifact-bottom">Explore this in the application ${icon('arrow')}</div></button><div class="showcase-stackline"><span>Custom software. Built around your business.</span><button onclick="showcaseStack()"><b>AI</b> Claude · OpenAI <i>/</i> <b>Workspace</b> Teams · SharePoint <i>/</i> <b>Platform</b> Azure · Supabase · Vercel ${icon('plus')}</button></div></section>`}
function showcaseHome(){const ids=toolsList.map((_,i)=>i).filter(i=>showcaseCategory==='All'||({Growth:[0,1,2,12],Delivery:[6,7,11],Decisions:[3,4,5,8,9,10]}[showcaseCategory]||[]).includes(i));return `<section class="collection-home"><div class="collection-intro"><div class="showcase-eyebrow"><span>NINE-67 / APPLICATION STUDIO</span></div><h1>See what AI can do<br>for the way you work.</h1><div class="collection-intro-bottom"><p>Thirteen purpose-built applications. Explore the workflows, change the inputs, and see what we can build around your business.</p><button class="showcase-primary" onclick="nav(0)">Start with Proposal Builder ${icon('arrow')}</button></div></div><div class="collection-feature"><div><span class="collection-feature-label">EXPLORE A CONNECTED WORKFLOW</span><h2>From the first opportunity<br>to the next successful delivery.</h2><p>Discover how research, proposals, planning, and collaboration can work together.</p></div><div class="collection-journey">${[[12,'Find the opportunity','Research & outreach'],[0,'Shape the response','Proposal & review'],[7,'Deliver together','Projects & collaboration']].map(([i,title,desc],n)=>`<button onclick="nav(${i})"><span class="journey-number">0${n+1}</span>${icon(productIcons[i])}<b>${title}</b><small>${desc}</small><span class="journey-arrow">↗</span></button>`).join('')}</div></div><div class="collection-toolbar"><div><h2>Explore the applications <span>13</span></h2><p>Choose a workflow to see it in action.</p></div><div class="collection-filters">${['All','Growth','Delivery','Decisions'].map(c=>`<button class="${c===showcaseCategory?'selected':''}" onclick="showcaseCategory='${c}';render()">${c}</button>`).join('')}</div></div><div class="collection-grid">${ids.map(i=>`<button class="collection-card" onclick="nav(${i})"><div class="collection-card-top"><span>${icon(productIcons[i])}</span><small>${String(i+1).padStart(2,'0')} / 13</small></div><h3>${esc(toolsList[i][0])}</h3><p>${esc(productStories[i].title)}</p><div class="collection-card-output">${esc(showcaseMeta[i][2])} <span>·</span> ${esc(showcaseMeta[i][3])}</div><div class="collection-card-bottom">${esc(showcaseMeta[i][0])} ${icon('arrow')}</div></button>`).join('')}</div><div class="collection-foot"><b>Built by Nine-67. Tailored to your team.</b><button onclick="showcaseStack()">Explore our technology toolkit ${icon('arrow')}</button><span>Sample data · Simulated AI · No live messages sent</span></div></section>`}
// Use one composition pass for the showcase instead of stacking header wrappers.
render=function(){renderBeforeIntroductions();showcaseSidebar();document.body.classList.remove('product-focus');$('.headerRight').innerHTML=`<span class="showcase-top-label">CLIENT SHOWCASE</span><button onclick="showcaseStack()">${icon('link')} Technology</button>${current>=0?'<button onclick="startWalkthrough()">'+icon('arrow')+' Guided tour</button>':''}`;$('#crumb').innerHTML=`<span class="showcase-breadcrumb">${current<0?'The collection':'Applications <span>/</span> '+esc(toolsList[current][0])}</span>`;if(current<0){$('#main').innerHTML=showcaseHome();return}$('#main').insertAdjacentHTML('afterbegin',showcaseHeader())};render();
